'use client';

import React from 'react';
import { GlobalSettings, ThemeData } from '@/types/cms';
import { ThemeAFooter } from '@/components/themes/theme-a/Footer';

interface FooterProps {
  theme?: ThemeData | null;
  settings?: GlobalSettings;
}

export const Footer: React.FC<FooterProps> = ({ theme, settings }) => {
  const activeTheme = theme?.directory_name || 'theme-a';

  if (activeTheme === 'theme-a') {
    return <ThemeAFooter theme={theme} settings={settings} />;
  }

  // Fallback / Theme B default footer
  const siteName = settings?.site_identity?.site_name || 'BestGroup';

  return (
    <footer className="bg-slate-950 border-t border-slate-900 text-slate-400 py-12 px-6 text-center text-xs">
      <div>&copy; {new Date().getFullYear()} {siteName}. All rights reserved.</div>
    </footer>
  );
};
export default Footer;
